export const GENERATED_MARKER =
  "// @generated by prisma-rust-generator — do not edit by hand";

// Densely connected Prisma schemas (the 14-stress 75-model fixture, for
// example) push drop-check and serde-derive recursion past the default 256.
// 1024 is enough for production schemas seen so far; raise if a real schema
// overflows.
export const CRATE_RECURSION_LIMIT_ATTR = `#![recursion_limit = "1024"]`;

export interface HeaderOpts {
  filePreamble: string;
  clippyAllowList: readonly string[];
}

export function emitFileHeader(opts: HeaderOpts): string {
  const parts: string[] = [GENERATED_MARKER];
  if (opts.filePreamble.length > 0) parts.push(opts.filePreamble.trimEnd());
  if (opts.clippyAllowList.length > 0) {
    parts.push(`#![allow(${opts.clippyAllowList.join(", ")})]`);
  }
  parts.push("");
  return parts.join("\n");
}
